/**
 * One Desk - short Lottie animations for key moments
 * (check in / out, break, resume, task start / complete).
 *
 *   OneDeskFx.play('task-complete', { title, subtitle })  -> true if shown
 *   OneDeskFx.mount(element, 'break', { loop: true })     -> stop() function
 *   OneDeskFx.enabled() / OneDeskFx.setEnabled(bool)
 *
 * Animations live in img/lottie/<name>.json (generated by scripts/build-lottie.mjs;
 * any LottieFiles "Lottie JSON" download can replace one). The lottie-web player
 * is loaded lazily the first time it's needed.
 */
(function () {
  'use strict';

  const PLAYER_URL = 'https://cdn.jsdelivr.net/npm/lottie-web@5.12.2/build/player/lottie_light.min.js';
  const PREF_KEY = 'onedesk_fx';
  const reducedMotion = () => window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  let playerPromise = null;
  const dataCache = new Map();
  let overlay = null;
  let current = null; // { anim, timer }

  function enabled() {
    try { return localStorage.getItem(PREF_KEY) !== 'off'; } catch (e) { return true; }
  }

  function setEnabled(on) {
    try { localStorage.setItem(PREF_KEY, on ? 'on' : 'off'); } catch (e) { }
  }

  function loadPlayer() {
    if (window.lottie) return Promise.resolve(window.lottie);
    if (!playerPromise) {
      playerPromise = new Promise((resolve, reject) => {
        const s = document.createElement('script');
        s.src = PLAYER_URL;
        s.async = true;
        s.onload = () => (window.lottie ? resolve(window.lottie) : reject(new Error('lottie missing')));
        s.onerror = () => { playerPromise = null; reject(new Error('lottie failed to load')); };
        document.head.appendChild(s);
      });
    }
    return playerPromise;
  }

  function loadData(name) {
    if (!dataCache.has(name)) {
      dataCache.set(name, fetch(`img/lottie/${name}.json`)
        .then((r) => { if (!r.ok) throw new Error(r.status); return r.json(); })
        .catch((e) => { dataCache.delete(name); throw e; }));
    }
    // Lottie mutates the data it's given, so hand out a copy each time.
    return dataCache.get(name).then((d) => JSON.parse(JSON.stringify(d)));
  }

  // Render an animation into `el`. Returns a promise of the lottie instance (or null).
  async function render(el, name, { loop = false } = {}) {
    try {
      const [lottie, data] = await Promise.all([loadPlayer(), loadData(name)]);
      el.innerHTML = '';
      const anim = lottie.loadAnimation({
        container: el, renderer: 'svg', loop, autoplay: !reducedMotion(), animationData: data,
        rendererSettings: { preserveAspectRatio: 'xMidYMid meet' },
      });
      // Reduced motion: show the finished frame instead of playing.
      if (reducedMotion()) anim.addEventListener('DOMLoaded', () => anim.goToAndStop(anim.totalFrames - 1, true));
      return anim;
    } catch (e) {
      console.warn('[OneDeskFx]', name, e);
      return null;
    }
  }

  function getOverlay() {
    if (overlay && document.body.contains(overlay)) return overlay;
    overlay = document.createElement('div');
    overlay.className = 'odfx-overlay';
    overlay.setAttribute('aria-live', 'polite');
    // Top layer, so it shows above open dialogs too.
    if (typeof overlay.showPopover === 'function') overlay.setAttribute('popover', 'manual');
    overlay.innerHTML = `
      <div class="odfx-card" role="status">
        <div class="odfx-anim"></div>
        <p class="odfx-title"></p>
        <p class="odfx-sub"></p>
      </div>`;
    overlay.addEventListener('click', hide);
    document.body.appendChild(overlay);
    return overlay;
  }

  function showLayer(el) {
    if (!el.hasAttribute('popover')) return;
    try {
      if (el.matches(':popover-open')) el.hidePopover(); // re-raise above newer dialogs
      el.showPopover();
    } catch (e) { }
  }

  // Moments that arrive while one is showing wait their turn (e.g. "Task completed"
  // followed by "Daily Plan cleared").
  const queue = [];

  function hide() {
    if (!overlay || !current) return;
    const { anim, timer } = current;
    current = null;
    clearTimeout(timer);
    overlay.classList.remove('is-visible');
    setTimeout(() => {
      if (current) return; // a new one started meanwhile
      try { anim && anim.destroy(); } catch (e) { }
      if (queue.length) {
        play(...queue.shift());
        return;
      }
      try { if (overlay.matches(':popover-open')) overlay.hidePopover(); } catch (e) { }
    }, 280);
  }

  const DURATIONS = {
    'task-complete': 2300, 'check-in': 2400, 'check-out': 2600,
    'goal-reached': 2800, 'qc-approved': 2600, 'plan-cleared': 2800, 'leave-approved': 2800,
  };

  /** Play a one-off animation card. Returns true if it will be shown. */
  function play(name, opts = {}) {
    if (!enabled() || document.hidden) return false;
    if (current) {
      if (queue.length < 3) queue.push([name, opts]);
      return true;
    }
    const { title = '', subtitle = '', duration } = opts;
    const el = getOverlay();
    current = { anim: null, timer: null };
    const mine = current;

    el.dataset.kind = name;
    el.querySelector('.odfx-title').textContent = title;
    const sub = el.querySelector('.odfx-sub');
    sub.textContent = subtitle;
    sub.hidden = !subtitle;
    const box = el.querySelector('.odfx-anim');
    box.innerHTML = '';

    showLayer(el);
    requestAnimationFrame(() => el.classList.add('is-visible'));
    render(box, name).then((anim) => {
      if (current !== mine) { try { anim && anim.destroy(); } catch (e) { } return; }
      mine.anim = anim;
    });
    mine.timer = setTimeout(hide, duration || DURATIONS[name] || 1800);
    return true;
  }

  /** Render an animation inside an existing element (e.g. a popup icon). Returns stop(). */
  function mount(el, name, opts = {}) {
    if (!el || !enabled()) return () => { };
    let anim = null, stopped = false;
    render(el, name, opts).then((a) => { if (stopped) { try { a && a.destroy(); } catch (e) { } } else anim = a; });
    return () => { stopped = true; try { anim && anim.destroy(); } catch (e) { } };
  }

  // Warm the player and the most common animations once the app is idle,
  // so the first celebration appears instantly.
  function warmUp() {
    if (!enabled()) return;
    loadPlayer().then(() => ['task-start', 'task-complete'].forEach((n) => loadData(n).catch(() => { }))).catch(() => { });
  }
  if ('requestIdleCallback' in window) requestIdleCallback(() => setTimeout(warmUp, 4000));
  else setTimeout(warmUp, 6000);

  window.OneDeskFx = { play, mount, hide, enabled, setEnabled };
})();
